/**
 * Convert text into a lowercase, URL-safe slug.
 * Runs of non-alphanumeric characters become a single hyphen; leading/trailing hyphens are removed.
 */
export function slugify(input: string): string {
  return input.toLowerCase().trim().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
}

/**
 * Shorten text to at most `max` characters, ending with "…" when truncated.
 * The ellipsis counts toward `max`.
 */
export function truncate(input: string, max: number): string {
  return input.length <= max ? input : input.slice(0, max - 1) + "…";
}

/**
 * Build uppercase initials from the first character of each whitespace-separated word.
 */
export function initials(name: string): string {
  return name.split(/\s+/).filter(Boolean).map((p) => p[0]!.toUpperCase()).join("");
}

